
function isLicensedPhoto(p){
 if(!p||!p.author||!p.file||!p.city||!p.taken||!p.checked||p.excludedFromDisplayV38)return false;
 const allowed=/^(CC0 1\.0|CC BY(?:-SA)? (?:2\.0|3\.0|4\.0)(?: PL)?|Public domain \(PD-self\))$/;
 return allowed.test(String(p.license||'')) &&
  /^https:\/\/commons\.wikimedia\.org\/wiki\/File:/.test(String(p.source||'')) &&
  /^https:\/\/commons\.wikimedia\.org\/wiki\/Special:FilePath\//.test(String(p.url||'')) &&
  (/^https:\/\/creativecommons\.org\//.test(String(p.licenseUrl||''))||p.license==='Public domain (PD-self)');
}


