const CITY_PHOTO_MAP=Object.fromEntries(PHOTO_CATALOG.filter(p=>p.cover).map(p=>[p.city,p]));
const SPOT_PHOTO_MAP=new Map();PHOTO_CATALOG.filter(p=>p.spot).forEach(p=>{const k=p.city+'|'+p.spot;const prior=SPOT_PHOTO_MAP.get(k);if(!prior||photoSortKey(p)>photoSortKey(prior))SPOT_PHOTO_MAP.set(k,p)});
const cityPhoto=(city,w=950)=>CITY_PHOTO_MAP[city]?.url||cityFallback(city);
function photoSortKey(p){const m=String(p?.taken||'').match(/^(\d{4})(?:-(\d{2}))?(?:-(\d{2}))?/);return m?`${m[1]}-${m[2]||'01'}-${m[3]||'01'}`:'0000-00-00'}
function spotPhoto(city,spot){return SPOT_PHOTO_MAP.get(city+'|'+spot)||null}
function spotGallery(city,spot){return PHOTO_CATALOG.filter(p=>p.city===city&&p.spot===spot).sort((a,b)=>photoSortKey(b).localeCompare(photoSortKey(a)))}
function recentPhoto(city,spot){return spotGallery(city,spot).some(p=>/^(202[4-9])(?:-|$)/.test(p.taken||''))}
function photoYear(p){const m=String(p?.taken||'').match(/^(\d{4})(?:-|$)/);return m?Number(m[1]):null}
function photoAgeLabel(p){
 if(!p)return '사진 미확인 · 대체 이미지';
 const y=photoYear(p);
 if(!y)return '촬영연도 미확인 · 원본 출처 참고';
 return y>=2024?`${y}년 촬영 · 비교적 최근 사진`:`${y}년 촬영 · 과거 모습일 수 있음`;
}
function photoStats(city){
 const spots=DATA[city].spots, covered=spots.filter(sp=>spotPhoto(city,sp[0]));
 const recent=covered.filter(sp=>recentPhoto(city,sp[0])).length;
 const old=covered.filter(sp=>spotGallery(city,sp[0]).every(p=>photoYear(p)&&photoYear(p)<2024)).length;
 const unknown=covered.length-recent-old;
 return {total:spots.length,covered:covered.length,recent,old,unknown,missing:spots.length-covered.length};
}

function photoCredit(p,compact=false){
 if(!p||!isLicensedPhoto(p))return '저작권·장소 확인 불가 · 대체 이미지';
 const original=`<a href="${safe(p.source)}" target="_blank" rel="noopener noreferrer">원본·사진명: ${safe(p.photoTitle||p.file)}</a>`;
 const author=`<a href="${safe(p.source)}" target="_blank" rel="noopener noreferrer">${safe(p.author)}</a>`;
 const license=`<a href="${safe(p.licenseUrl)}" target="_blank" rel="noopener noreferrer">${safe(p.license)}</a>`;
 const change=p.siteModification||'원본 파일 미수정 · 화면 맞춤 일부 잘림';
 const verified=p.metadataVerifiedThisRun?'v37 원본 개별 확인':'이전 버전 출처 기록(이번 재확인 아님)';
 return compact?`사진: ${author} · ${license} · ${original} · 촬영 ${safe(p.taken||'미확인')} · ${change} · 확인기록 ${safe(p.checked)}`:
 `사진: ${original} · 저작자 ${author} · ${license} · 촬영 ${safe(p.taken||'미확인')} · 확인 ${safe(p.checked)} (${verified}) · ${change}${String(p.license).includes('BY-SA')?' · 수정본 배포 시 동일조건 공유':''}`;
}
function setCuratedImage(img,p,place,noteEl,requestedWidth=0){
 if(!img)return;
 img.onload=null;img.onerror=null;
 const fallback=cityFallback(place||'여행지');
 img.style.backgroundImage='url("'+fallback+'")';
 img.style.backgroundSize='cover';img.style.backgroundPosition='center';
 img.decoding='async';
 img.alt=p?`${place} · ${p.label||'현지 촬영 사진'} · 사진: ${p.author}`:`${place} 사진 미확인 · 대체 이미지`;
 img.dataset.photoStatus=p?'loading':'fallback';
 if(!p || !isLicensedPhoto(p)){img.src=fallback;if(noteEl)noteEl.textContent='해당 관광지 사진 미확인 · 대체 이미지';return}
 img.onload=()=>{
  img.dataset.photoStatus='loaded';
  if(noteEl && !noteEl.querySelector('.load-status')){
   const span=document.createElement('span');span.className='load-status';span.textContent=' · 현재 브라우저에서 사진 표시됨';noteEl.append(span);
  }
 };
 img.onerror=()=>{
  img.onerror=null;img.onload=null;img.dataset.photoStatus='fallback';img.src=fallback;
  img.alt=`${place} 사진 연결 실패 · 대체 이미지`;
  if(noteEl)noteEl.innerHTML='⚠️ 외부 사진 연결 실패 · 대체 이미지 표시. '+photoCredit(p)+' · '+safe(photoAgeLabel(p));
 };
 img.src=requestedWidth ? p.url.replace(/([?&]width=)\d+/, '$1'+requestedWidth) : p.url;
}
function renderPhotoCredits(city){
 const items=PHOTO_CATALOG.filter(p=>p.city===city).sort((a,b)=>photoSortKey(b).localeCompare(photoSortKey(a)));
 $('photoCredits').innerHTML=items.map(p=>`<article><strong>${safe(p.label)}</strong><span>사진명: ${safe(p.photoTitle||p.file)}</span><span>저작자: ${safe(p.author)} · 촬영: ${safe(p.taken||'미확인')} · 출처 확인 기록: ${safe(p.checked)}</span><span>라이선스: ${safe(p.license)} · ${p.lastVerifiedVersion==='v38'?'v38 원본 개별 확인 (v40 재검증 아님)':p.lastVerifiedVersion==='v37'?'v37 확인 기록 계승':'이전 버전 기록 계승(이번 재검증 아님)'}</span><span>수정 여부: ${safe(p.siteModification||'이 사이트에서 원본 파일 수정 없음; CSS 화면 맞춤 일부 잘림')}</span><span>이용 조건: ${safe(p.reuseTerms||'원본 라이선스 조건 확인')}</span><span>${safe(p.scene||'')}</span><a href="${safe(p.source)}" target="_blank" rel="noopener noreferrer">원본 사진·제목 확인 ↗</a><a href="${safe(p.licenseUrl)}" target="_blank" rel="noopener noreferrer">라이선스 전문 ↗</a></article>`).join('');
 const stats=photoStats(city);
 $('photoStatus').textContent=`📷 사진 ${stats.covered}/${stats.total}곳 (${items.length}장) · 2024년 이후 촬영 ${stats.recent}곳 · 과거 촬영만 ${stats.old}곳 · 촬영연도 미확인 ${stats.unknown}곳 · 사진 없음 ${stats.missing}곳`;
 const reviewed=items.filter(p=>p.metadataVerifiedThisRun).length;
 $('photoAuditSummary').innerHTML=`<strong>v38 저작권 점검</strong> · v38 원본 개별 재확인 ${items.filter(p=>p.lastVerifiedVersion==='v38').length}장 / 기존 확인 기록 계승 ${items.filter(p=>p.lastVerifiedVersion!=='v38').length}장.<br>사진은 원본 파일을 변경하지 않고 외부 Commons 이미지를 표시합니다. CSS 화면 맞춤으로 일부가 잘려 보일 수 있습니다. CC BY-SA 사진을 실제 수정해 재배포하면 동일조건 공유가 필요할 수 있습니다. 출처 표시만으로 무단 이용이 허용되는 것은 아닙니다.`;
}
function cityFallback(city){
 const label=safe(city||'여행지');
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="960" height="520" viewBox="0 0 960 520"><defs><linearGradient id="g" x2="1" y2="1"><stop stop-color="#14586e"/><stop offset="1" stop-color="#38afa1"/></linearGradient></defs><rect width="960" height="520" fill="url(#g)"/><circle cx="735" cy="130" r="70" fill="#f4df9c" opacity=".9"/><path d="M0 400 L220 190 410 370 560 235 790 460 960 290 V520 H0Z" fill="#0d4761" opacity=".65"/><path d="M0 475 L300 305 520 460 740 350 960 480 V520 H0Z" fill="#103b58" opacity=".7"/><text x="55" y="105" fill="#fff" font-family="sans-serif" font-size="44" font-weight="bold">${label}</text><text x="57" y="153" fill="#e5faf5" font-family="sans-serif" font-size="24">실제 사진 미확인 또는 연결 실패</text></svg>`;
 return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
}
function toast(t){$('toast').textContent=t;$('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),2800)}
function show(id){for(const k of ['discover','planner','saved'])$(k).classList.toggle('hidden',id!==k);document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===id));if(id==='saved')renderSaved();scrollTo({top:0,behavior:'instant'})}
function duration(){let a=$('start').value,b=$('end').value;if(!a||!b)return 0;let n=Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000)+1;return n>0&&n<=60?n:0}
function dateLabel(i){let d=new Date($('start').value+'T12:00:00');d.setDate(d.getDate()+i);return d.toLocaleDateString('ko-KR',{month:'numeric',day:'numeric',weekday:'short'})}
function nameAuto(){if(manual)return;let a=$('start').value,b=$('end').value;$('tripName').value=`${$('origin').value}-${$('city').value} ${a}${b?'~'+(a.slice(0,4)===b.slice(0,4)?b.slice(5):b):''}`.trim()}
function syncDays(){let n=duration();if(!n)return false;days=Array.from({length:n},(_,i)=>days[i]||[]);active=Math.min(active,n-1);return true}
function totals(){let people=Math.max(1,Math.floor(num($('people').value)||1)),rooms=Math.max(1,Math.floor(num($('rooms').value)||1)),nights=Math.max(0,duration()-1),activities=days.flat().reduce((sum,x)=>sum+num(x.cost),0),total=costs.reduce((sum,v,i)=>sum+num(v)*(i===0?people:i===1?nights*rooms:1),0)+activities;return{people,rooms,nights,activities,total}}
function refreshReadiness(){
 const filled=days.filter(a=>a.length>0).length,complete=TASKS.filter((_,i)=>!!checks[i]).length;
 $('readyDays').textContent=`${filled}/${days.length}일`;
 $('readyChecks').textContent=`${complete}/${TASKS.length}개`;
  $('readyConflicts').textContent=allConflictCount()+'건';
 $('readyAverage').textContent=won(duration()?totals().total/duration():0);
 const empty=days.findIndex(a=>a.length===0);
 $('goEmptyDay').disabled=empty<0;
 $('goEmptyDay').textContent=empty<0?'모든 날짜에 일정이 있습니다':`${empty+1}일차 빈 날짜로 이동`;
 $('readyHint').textContent=days.length===0?'여행 날짜를 입력하면 일정 완성도를 확인할 수 있습니다.':empty<0?'모든 날짜에 일정이 있습니다. 예약·이동시간을 점검하세요.':`아직 일정이 없는 날짜가 ${days.length-filled}일 있습니다.`;
}
function renderBreakdown(){
 const t=totals(),groups=[['항공료',num(costs[0])*t.people],['숙박비',num(costs[1])*t.nights*t.rooms],['현지 경비',costs.slice(2).reduce((a,b)=>a+num(b),0)],['일정별 비용',t.activities]];
 $('costBreakdown').innerHTML=groups.map(([label,value])=>`<div class="breakdown-item"><div class="breakdown-label"><span>${label}</span><strong>${won(value)}</strong></div><div class="breakdown-track"><div class="breakdown-fill" style="width:${t.total?Math.min(100,value/t.total*100):0}%"></div></div></div>`).join('');
}
function filterCities(){let q=$('citySearch').value.trim().toLocaleLowerCase(),country=$('countryFilter').value,n=0;document.querySelectorAll('[data-city]').forEach(b=>{let c=DATA[b.dataset.city],hit=(!country||c.country===country)&&(!q||(b.dataset.city+' '+c.country+' '+c.tag+' '+c.intro).toLocaleLowerCase().includes(q));b.closest('.city').classList.toggle('hidden',!hit);if(hit)n++});$('cityCount').textContent=`${n}개 도시 표시`;$('cityEmpty').classList.toggle('hidden',n!==0)}
function renderCityGuide(city){let labels=['공항에서 시내','현지 이동','추천 동선','알아두면 좋은 팁'];let a=CITY_GUIDES[city]||['공항·시내 이동 수단과 운행시간을 공식 교통기관에서 확인하세요.','도심은 대중교통·도보, 외곽 명소는 투어·차량 이동을 비교하세요.','가까운 관광지 2~3곳을 하루에 묶고 먼 근교 코스는 별도 하루를 확보하세요.','입장료·운영시간·휴무일·날씨는 여행 직전에 공식 사이트에서 확인하세요.'];$('cityGuide').innerHTML=a.map((v,i)=>`<div class="guide-card"><strong>${labels[i]}</strong>${safe(v)}</div>`).join('')}
function moveActivity(i,to){if(!Number.isInteger(to)||to<0||to>=days.length||to===active)return;const item=days[active].splice(i,1)[0];if(!item)return;days[to].push(item);active=to;renderDays();refresh();toast(`${to+1}일차로 일정을 이동했습니다`)}
function sortActiveDay(){if(!days.length)return;days[active].sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'));renderDays();toast('시간순으로 정렬했습니다')}
function refresh(){let t=totals(),budget=num($('budget').value);$('sumDays').textContent=duration()?duration()+'일':'날짜 확인';$('sumPeople').textContent=t.people+'명';$('sumNights').textContent=t.nights+'박 · '+t.rooms+'객실';$('sumTotal').textContent=won(t.total);$('sumPer').textContent=won(t.total/t.people);$('sumBudget').textContent=budget?(budget>=t.total?'잔여 ':'초과 ')+won(Math.abs(budget-t.total)):'목표 미설정';$('budgetProgress').style.width=budget?Math.min(100,t.total/budget*100)+'%':'0%';let c=DATA[$('city').value],a=$('start').value,b=$('end').value;if(c&&duration())$('flightLink').href=`https://flight.naver.com/flights/international/${$('origin').value}:airport-${c.airport}:airport-${a.replaceAll('-','')}/${c.airport}:airport-${$('origin').value}:airport-${b.replaceAll('-','')}?adult=${t.people}&isDirect=true&fareType=Y`;else $('flightLink').href='https://flight.naver.com/';$('hotelLink').href='https://www.booking.com/searchresults.ko.html?ss='+encodeURIComponent($('city').value);renderBreakdown();refreshReadiness()}
function renderCosts(){$('costInputs').innerHTML=COST_LABELS.map((label,i)=>`<label class="cost-row"><span>${label}</span><input type="number" min="0" step="1000" data-cost="${i}" value="${costs[i]}" aria-label="${label}"></label>`).join('');document.querySelectorAll('[data-cost]').forEach(e=>e.oninput=()=>{costs[+e.dataset.cost]=num(e.value);refresh()})}
function renderChecks(){$('checklist').innerHTML=TASKS.map((x,i)=>`<label class="check"><input type="checkbox" data-check="${i}" ${checks[i]?'checked':''}>${x}</label>`).join('');document.querySelectorAll('[data-check]').forEach(e=>e.onchange=()=>{checks[e.dataset.check]=e.checked;refreshReadiness()})}
function reorderActivity(i,offset){
 const arr=days[active]||[],j=i+offset;
 if(i<0||i>=arr.length||j<0||j>=arr.length)return;
 [arr[i],arr[j]]=[arr[j],arr[i]];
 renderDays();refresh();toast('일정 표시 순서를 변경했습니다. 시간은 그대로 유지됩니다.');
}

/* v20: non-destructive schedule feasibility estimate (no routing API) */
function activityStayMinutes(city,place){
  const sp=(DATA[city]?.spots||[]).find(x=>x[0]===place);
  return sp?Math.max(15,Number(sp[3])||60):60;
}
function activityStartMinutes(time){
  const match=String(time||'').match(/^([01]\d|2[0-3]):([0-5]\d)$/);
  return match?Number(match[1])*60+Number(match[2]):null;
}
function checkDayFeasibility(arr,city,buffer){
  const valid=(arr||[]).map((item,index)=>({...item,index,startMinute:activityStartMinutes(item.time)}))
    .filter(item=>item.startMinute!==null).sort((a,b)=>a.startMinute-b.startMinute);
  const conflicts=[];
  for(let i=1;i<valid.length;i++){
    const prev=valid[i-1],next=valid[i],stay=activityStayMinutes(city,prev.place),need=prev.startMinute+stay+buffer;
    if(next.startMinute<need)conflicts.push({first:prev.place,second:next.place,shortBy:need-next.startMinute,firstTime:prev.time,secondTime:next.time});
  }
  return {conflicts,scheduled:valid.length,unplanned:(arr||[]).length-valid.length};
}
function renderScheduleWarnings(){
  const box=$('scheduleWarnings');if(!box)return;
  const buffer=Math.max(0,Number($('travelBuffer')?.value)||0),city=$('city').value;
  const result=checkDayFeasibility(days[active]||[],city,buffer);
  box.classList.toggle('has-conflicts',result.conflicts.length>0);
  if(!days.length){box.textContent='여행 날짜를 입력하면 시간 겹침을 검토할 수 있습니다.';return}
  if(!result.conflicts.length){box.innerHTML='<strong>✓ 예상 시간 겹침 없음</strong>등록한 시작시간과 관광지 권장 체류시간 기준입니다. 이동경로·영업시간·예약시간은 별도 확인하세요.';return}
  box.innerHTML=`<strong>⚠ 예상 시간 겹침 ${result.conflicts.length}건</strong>아래 일정은 관광지 체류시간과 여유시간을 고려하면 촉박할 수 있습니다.<ul>${result.conflicts.map(c=>`<li>${safe(c.firstTime)} ${safe(c.first)} → ${safe(c.secondTime)} ${safe(c.second)} · 약 ${c.shortBy}분 부족</li>`).join('')}</ul><small>※ 교통수단별 실제 이동시간은 반영되지 않습니다. 시간이 겹쳐도 일정은 자동 변경하지 않습니다.</small>`;
}
function allConflictCount(){const buffer=Math.max(0,Number($('travelBuffer')?.value)||0),city=$('city').value;return days.reduce((sum,d)=>sum+checkDayFeasibility(d,city,buffer).conflicts.length,0)}

function renderDays(){
 $('dayTabs').innerHTML=days.map((_,i)=>`<button data-day="${i}" class="${i===active?'active':''}">${i+1}일차 · ${dateLabel(i)}</button>`).join('');
 document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{active=+b.dataset.day;renderDays()});
 const arr=days[active]||[];
 $('dayStats').textContent=days.length?`${active+1}일차 · ${arr.length}개 일정 · 예상 현장 지출 ${won(arr.reduce((a,x)=>a+num(x.cost),0))}`:'';
  renderScheduleWarnings();
 $('dayItems').innerHTML=!days.length?'<div class="empty">날짜별 일정표를 먼저 만드세요.</div>':!arr.length?'<div class="empty">관광지를 선택하거나 직접 일정을 추가하세요.</div>':arr.map((x,i)=>`<div class="activity"><div class="row"><strong>${safe(x.time||'시간 미정')} · ${safe(x.place)}</strong><div class="activity-tools"><button class="btn alt reorder-btn" data-reorder="${i}" data-offset="-1" ${i===0?'disabled':''} aria-label="${safe(x.place)} 위로 이동" title="위로 이동">↑</button><button class="btn alt reorder-btn" data-reorder="${i}" data-offset="1" ${i===arr.length-1?'disabled':''} aria-label="${safe(x.place)} 아래로 이동" title="아래로 이동">↓</button>${days.length>1?`<label class="small muted">이동 <select data-move="${i}" aria-label="${safe(x.place)} 일정 날짜 이동">${days.map((_,d)=>`<option value="${d}" ${d===active?'selected':''}>${d+1}일차</option>`).join('')}</select></label>`:''}<button class="btn alt" data-edit="${i}">수정</button><button class="btn danger" data-del="${i}">삭제</button></div></div><p>${safe(x.memo||'')}${x.cost?' · '+won(x.cost):''}</p><a class="link small" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(x.place+' '+$('city').value)}">지도 보기 ↗</a></div>`).join('');
 document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(+b.dataset.edit));
 document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{if(confirm('이 일정을 삭제할까요?')){days[active].splice(+b.dataset.del,1);renderDays();refresh()}});
 document.querySelectorAll('[data-move]').forEach(b=>b.onchange=()=>moveActivity(+b.dataset.move,+b.value));
 document.querySelectorAll('[data-reorder]').forEach(b=>b.onclick=()=>reorderActivity(+b.dataset.reorder,+b.dataset.offset));
}
function edit(i=-1){if(!days.length){toast('날짜별 일정표를 먼저 만드세요');return}let x=i<0?{time:'09:00',place:'',memo:'',cost:0}:days[active][i];$('editor').innerHTML=`<div class="notice" style="margin-top:12px"><h3>${i<0?'일정 추가':'일정 수정'}</h3><div class="grid2"><label class="field">시간<input id="eTime" type="time" value="${safe(x.time)}"></label><label class="field">장소<input id="ePlace" maxlength="150" value="${safe(x.place)}"></label><label class="field">예상비용 (원)<input id="eCost" type="number" min="0" value="${num(x.cost)}"></label><label class="field">메모<input id="eMemo" maxlength="500" value="${safe(x.memo)}"></label></div><div class="actions" style="margin-top:12px"><button id="eSave" class="btn">반영</button><button id="eCancel" class="btn alt">취소</button></div></div>`;$('eCancel').onclick=()=>$('editor').innerHTML='';$('eSave').onclick=()=>{let place=$('ePlace').value.trim();if(!place){toast('장소를 입력하세요');return}let item={time:$('eTime').value,place,memo:$('eMemo').value,cost:num($('eCost').value)};if(i<0)days[active].push(item);else days[active][i]=item;$('editor').innerHTML='';renderDays();refresh()}}
function visitTip(sp){if(/시장|야시장|먹거리|미식/.test(sp[2]))return'식사 시간에는 혼잡할 수 있습니다. 현금·카드 사용 가능 여부와 위생 상태를 확인하세요.';if(/박물관|미술관|테마파크/.test(sp[2]))return'입장권 사전예약과 휴관일·혼잡시간을 확인하면 대기시간을 줄일 수 있습니다.';if(/사원|문화|역사/.test(sp[2]))return'복장 규정, 촬영 가능 구역, 현지 예절을 방문 전에 확인하세요.';if(/야경|전망|사진/.test(sp[2]))return'일몰 전후 빛이 좋은 시간대가 인기 있습니다. 날씨에 따라 전망이 달라집니다.';if(/해변|휴양/.test(sp[2]))return'강한 햇빛과 해상 기상에 대비하고 수영 가능 구역을 확인하세요.';return'날씨와 혼잡도를 고려해 여유 시간을 확보하세요.'}
function transitTip(city,sp){if(['도쿄','오사카','타이베이','싱가포르','후쿠오카','홍콩','파리'].includes(city))return'시내 대중교통 노선과 도보 이동시간을 지도에서 확인하세요. 근교 명소는 왕복 이동시간을 별도로 잡으세요.';return'현지 차량 호출·택시 또는 투어 이동을 검토하고, 출퇴근 혼잡 및 우천 시 지연에 대비하세요.'}
let lastSpotCity='';
function filterSpots(){
 const city=$('city').value,c=DATA[city];if(!c)return;
 const query=$('spotSearch').value.trim().toLocaleLowerCase(),category=$('spotCategory').value,photoOnly=$('onlyPhotos').checked,recentOnly=$('recentPhotos').checked,oldOnly=$('oldPhotos').checked;
 let count=0;
 document.querySelectorAll('[data-spot-card]').forEach(card=>{
  const sp=c.spots[+card.dataset.spotCard];
  const hit=(!category||sp[2]===category)&&(!query||(sp[0]+' '+sp[1]+' '+sp[2]).toLocaleLowerCase().includes(query))&&(!photoOnly||!!spotPhoto(city,sp[0]))&&(!recentOnly||recentPhoto(city,sp[0]))&&(!oldOnly||(!!spotPhoto(city,sp[0])&&!recentPhoto(city,sp[0])&&spotGallery(city,sp[0]).every(p=>photoYear(p)&&photoYear(p)<2024)));
  card.classList.toggle('hidden',!hit);if(hit)count++;
 });
 $('spotCount').textContent=`${count}/${c.spots.length}곳 표시`;
 $('spotEmpty').classList.toggle('hidden',count!==0);
}
function renderSpotFilters(city){
 if(lastSpotCity!==city){$('spotSearch').value='';$('spotCategory').value='';lastSpotCity=city}
 const selected=$('spotCategory').value;
 const tags=[...new Set(DATA[city].spots.map(sp=>sp[2]))];
 $('spotCategory').innerHTML='<option value="">전체 테마</option>'+tags.map(tag=>`<option value="${safe(tag)}">${safe(tag)}</option>`).join('');
 if(tags.includes(selected))$('spotCategory').value=selected;
}
function visitWindow(sp){
 const cat=sp[2]||'';
 if(/야경|야시장/.test(cat))return'일몰 전후부터 저녁 시간대가 어울릴 수 있습니다. 현지 운영시간을 확인하세요.';
 if(/해변|휴양|자연/.test(cat))return'햇볕이 덜 강한 오전 또는 늦은 오후를 고려하세요. 기상 상황이 우선입니다.';
 if(/박물관|미술관|역사|문화/.test(cat))return'개장 시간과 휴관일을 확인한 뒤 오전 또는 오후로 넉넉히 배치하세요.';
 if(/시장|미식|먹거리/.test(cat))return'식사시간 전후 혼잡을 고려하세요. 상점별 영업시간은 다릅니다.';
 return'혼잡·날씨·이동시간을 고려해 방문 시간대를 조정하세요.';
}
function reservationTip(sp){
 const cat=sp[2]||'';
 if(/테마파크|박물관|미술관|전망/.test(cat))return'시간 지정 입장권, 휴관일, 사전예약 필요 여부를 공식 운영처에서 확인하세요.';
 if(/투어|섬|해변|자연/.test(cat))return'교통편과 기상에 따른 운영 변경, 예약·취소 조건을 확인하세요.';
 return'입장료·운영시간·예약 여부는 현지 공식 안내에서 최종 확인하세요.';
}

const SPOT_STORIES={"오사카|도톤보리":["에비스바시에서 글리코 간판을 보고, 도톤보리 강변과 주변 먹거리 골목을 천천히 둘러보세요.","간판 조명이 켜진 저녁이 분위기 있습니다. 인파가 많아 촬영할 때 보행을 방해하지 않도록 주의하세요."],"도쿄|센소지":["가미나리몬 → 나카미세 상점가 → 센소지 본당 순서로 걸으면 아사쿠사의 대표 풍경을 만날 수 있습니다.","인파를 피하고 싶다면 이른 오전을 고려하세요. 상점가 영업시간과 사찰 예절을 확인하세요."],"나트랑|나트랑 해변":["해변 산책로를 걸으며 바다를 감상하고, 카페·휴식 시간을 넉넉히 넣어보세요.","햇빛이 부드러운 아침 산책이 좋습니다. 해상 상태와 수영 가능 구역은 현장에서 확인하세요."],"다낭|호이안 올드타운":["구시가지의 오래된 건축물과 투본강 주변을 걸으며 낮 풍경과 저녁 분위기를 비교해 보세요.","해 질 무렵 등불이 켜지면 분위기가 달라집니다. 다낭 숙소로 돌아가는 차량을 미리 확인하세요."],"타이베이|지우펀":["좁은 골목과 찻집, 계단길을 천천히 둘러보고 바다가 보이는 전망 포인트를 찾아보세요.","비 오는 날 계단이 미끄러울 수 있습니다. 주말과 저녁은 혼잡하며 귀가 교통편을 미리 확인하세요."],"방콕|왓 아룬":["사원의 세부 장식과 탑을 가까이 보고, 강 건너편에서는 강과 사원을 함께 담아보세요.","종교시설 복장 규정을 확인하세요. 일몰 전후 사진은 아름답지만 실제 입장 종료시간은 별도 확인이 필요합니다."],"싱가포르|가든스 바이 더 베이":["슈퍼트리 그로브를 둘러본 뒤 플라워돔·클라우드 포레스트 등 실내 정원과 조합해 보세요.","주간 정원과 야간 조명 분위기가 다릅니다. 유료 온실·행사 운영시간은 공식 안내에서 확인하세요."],"세부|막탄 해변":["리조트 해변에서 휴식을 즐기거나 운영 중인 해양활동을 선택해 일정을 구성하세요.","사진에 나온 특정 리조트 해변은 일반 해변과 접근 조건이 다를 수 있습니다. 출입·예약·날씨를 확인하세요."],"발리|뜨갈랄랑 계단식 논":["논 사이 산책길과 전망 카페에서 서로 다른 각도의 계단식 논 풍경을 감상해 보세요.","오전에는 비교적 덜 덥지만 우천 후 길이 미끄러울 수 있습니다. 개별 전망시설 이용료는 현장 확인이 필요합니다."],"파리|에펠탑":["트로카데로 광장과 샹드마르스 공원에서 서로 다른 구도로 에펠탑을 감상해 보세요.","전망대에 올라갈 계획이라면 공식 예약·입장시간을 확인하세요. 사진 촬영 때 소지품 관리에 유의하세요."],"후쿠오카|오호리 공원":["호수 주변 산책길을 따라 걸으며 다리와 정원 풍경을 즐기고, 근처 카페에서 쉬어가세요.","날씨 좋은 오전이나 늦은 오후가 산책하기 편합니다. 계절에 따라 주변 경관이 달라집니다."],"홍콩|빅토리아 피크":["전망대에서 빅토리아 하버와 도심의 밀집된 건물을 내려다보고, 시간에 여유가 있다면 주변 산책로도 살펴보세요.","안개·비가 심하면 전망이 제한됩니다. 피크트램 혼잡과 마지막 하산 교통편을 확인하세요."]};
const SPOT_PRACTICAL={"싱가포르|머라이언 파크":{"admission":"머라이언 파크 야외 구역은 일반적으로 무료입니다. 행사·주변 유료 시설은 별도 확인하세요.","transit":"MRT 래플스 플레이스(Raffles Place)역에서 마리나 베이 방향으로 도보 이동. 무더위·소나기에 대비하세요."},"도쿄|메이지 신궁":{"admission":"신궁 기본 참배는 일반적으로 무료이며, 일부 시설·특별 전시는 별도 요금이 있을 수 있습니다.","transit":"JR 하라주쿠역 또는 도쿄메트로 메이지진구마에역에서 도보. 신궁 입구부터 본전까지 숲길 이동시간을 포함하세요."},"후쿠오카|오호리 공원":{"admission":"공원 산책은 일반적으로 무료입니다. 정원·박물관 등 일부 시설은 별도 요금이 있을 수 있습니다.","transit":"후쿠오카시 지하철 오호리코엔역에서 도보. 호수 둘레를 천천히 걷는 산책 코스에 적합합니다."},"발리|울루와뚜 사원":{"admission":"입장료 및 케착 공연 요금은 변동될 수 있습니다. 공식 안내·현장 매표소에서 확인하세요.","transit":"발리 남부에서 차량·기사 포함 교통편 이용을 검토하세요. 일몰 무렵 혼잡과 귀가 차량 확보에 유의하세요."}};
Object.assign(SPOT_STORIES,{"싱가포르|머라이언 파크":["마리나 베이의 상징적인 머라이언 조각상과 건너편 스카이라인을 한 장의 사진에 담아보세요. 주변 수변 산책로를 따라 마리나 베이 샌즈 방향으로 이어 걷기 좋습니다.","낮에는 조각상과 분수의 디테일, 해 질 무렵에는 수변 조명을 비교해 보세요. 2025년 사진은 촬영 당시 모습입니다."],"도쿄|메이지 신궁":["도심 한가운데 조용한 숲길을 따라 도리이를 지나 신궁으로 향해 보세요. 시부야·하라주쿠의 번화가와 대비되는 분위기가 매력적입니다.","2025년 입구 사진은 참배길의 실제 모습입니다. 종교시설의 촬영 제한과 참배 예절을 존중하세요."],"후쿠오카|오호리 공원":["넓은 호수와 우키미도 정자, 연결 다리와 수변 산책길이 어우러집니다. 같은 장소도 호수 밖 풍경과 정자 내부에서 보는 모습이 다릅니다.","2026년 촬영한 호수·정자 사진 두 장을 새로 추가했습니다. 여름에는 햇빛을 피할 시간대를 고려하세요."],"발리|울루와뚜 사원":["절벽 위에 자리한 사원 주변에서 인도양의 풍경을 감상하세요. 일몰을 기다리는 일정이라면 이동·입장 대기시간을 충분히 잡으세요.","새 사진 두 장은 사원 건물 자체가 아닌 울루와뚜 주변 절벽·바다 풍경입니다. 원숭이와 개인 소지품에 유의하세요."]});
