Object.assign(SPOT_STORIES,{"오사카|우메다 스카이 빌딩":["두 타워를 잇는 독특한 고층 건축을 아래에서 올려다보고, 주변 녹지와 함께 전체 실루엣을 비교해 보세요. 실내 전망대에 오를 계획이라면 관람·이동 시간을 따로 확보하세요.","2025년 근접 사진과 그랜드그린 오사카에서 본 전경을 추가했습니다. 전망대는 날씨와 혼잡에 따라 체감이 달라질 수 있습니다."],"홍콩|스타페리":["침사추이에서 홍콩섬으로 배를 타며 빅토리아 하버의 밀집된 스카이라인을 수면 가까이에서 감상해 보세요. 낮에는 선박과 도시 디테일, 저녁에는 조명이 매력적입니다.","2024년 실제 운항 중인 스타페리 사진을 추가했습니다. 노선·막차·선착장 위치와 날씨에 따른 운항 변경을 확인하세요."],"싱가포르|차이나타운":["차이나타운의 거리 풍경과 사우스브리지로드의 역사적 상가 건물을 함께 보며 다양한 문화가 만나는 동네를 걸어보세요.","2024년 거리 사진의 출처를 재확인하고 2025년 건축 디테일 사진을 추가했습니다. 야외에서는 햇볕과 갑작스러운 비에 대비하세요."],"방콕|왕궁":["태국 전통 장식과 지붕·첨탑의 세밀한 문양을 가까이에서 관찰해 보세요. 넓은 구역을 걸으므로 충분한 시간과 물을 준비하는 편이 좋습니다.","2024년 왕궁 건축물 근접 사진입니다. 복장 규정·휴관·의전 행사로 인한 입장 제한은 공식 운영 안내를 확인하세요."],"파리|센강 산책":["퐁뇌프 다리에서 강을 바라본 뒤 강변 산책로를 따라 파리의 일상을 느껴보세요. 날씨가 좋은 날에는 강변에서 쉬는 사람들과 다리 풍경이 어우러집니다.","2025년 센강 낮 풍경과 여름 강변 산책로 사진을 추가했습니다. 강변 일부 구간은 수위·행사에 따라 접근이 제한될 수 있습니다."],"발리|타나롯 사원":["바다와 바위 위 사원이 함께 보이는 풍경으로 유명합니다. 일몰 전부터 주변 전망 지점을 살펴보고 해가 지는 동안 변화하는 빛을 감상해 보세요.","2025년 일몰 촬영 사진입니다. 파도와 조수 간만의 차이, 보행 가능 구역, 현지 예절에 유의하세요."]});
Object.assign(SPOT_PRACTICAL,{"오사카|우메다 스카이 빌딩":{"transit":"오사카·우메다 역세권에서 도보 이동을 계획하세요. 대형 역의 출구와 건물 입구를 지도에서 확인하면 편합니다.","admission":"주변 외관 관람과 유료 전망대 입장은 구분됩니다. 전망대 최신 요금·운영시간은 공식 운영처에서 확인하세요."},"홍콩|스타페리":{"transit":"침사추이·센트럴·완차이 등 이용할 선착장과 노선을 확인하세요. 선착장 간 위치와 배차는 시간대별로 달라질 수 있습니다.","admission":"여객선 탑승은 유료이며 선실 등급·노선에 따라 요금이 다릅니다. 운항사 최신 요금을 확인하세요."},"싱가포르|차이나타운":{"transit":"MRT 차이나타운역 주변을 기준으로 도보 탐방하기 편합니다. 사우스브리지로드와 주변 상점가를 함께 살펴보세요.","admission":"일반 거리 산책은 무료이나 개별 박물관·체험·시설 입장료는 별도입니다."},"방콕|왕궁":{"transit":"짜오프라야강 보트·대중교통·차량을 조합해 접근할 수 있습니다. 교통혼잡과 보안 검색 대기시간을 고려하세요.","admission":"왕궁 입장권은 유료일 수 있으며 외국인·현지인 요금과 관람 구역이 다릅니다. 공식 왕궁 안내에서 확인하세요."},"파리|센강 산책":{"transit":"퐁뇌프·오르세·시테섬 주변 대중교통에서 강변으로 접근해 걷기 좋습니다. 실제 산책 구간과 접근 가능한 계단을 지도에서 확인하세요.","admission":"공개 강변 산책로는 일반적으로 무료이나 유람선·전시·체험은 유료입니다."},"발리|타나롯 사원":{"transit":"발리 남서부 해안의 타나롯 일대는 차량 이동이 일반적입니다. 일몰 후 귀가 차량과 교통체증을 미리 고려하세요.","admission":"사원 관광구역 입장료·주차료는 변경될 수 있습니다. 공식 안내·현장 매표소에서 확인하세요."}});

/* v20: photographic exploration using only catalogued, attributed Commons photos */
function distinctCityPhotos(city,limit=5){
 const result=[],used=new Set();
 for(const p of PHOTO_CATALOG.filter(x=>x.city===city&&x.spot).sort((a,b)=>photoSortKey(b).localeCompare(photoSortKey(a)))){
  if(used.has(p.spot))continue;used.add(p.spot);result.push(p);if(result.length>=limit)break;
 }
 return result;
}
function renderCityPhotoGallery(city){
 const items=distinctCityPhotos(city,5);
 $('cityPhotoGalleryCount').textContent=`${items.length}개 명소 · 사진은 촬영 당시 모습`;
 $('cityPhotoGallery').innerHTML=items.map((p,i)=>{
  const index=DATA[city].spots.findIndex(x=>x[0]===p.spot);
  return `<article class="city-photo-item"><button type="button" data-city-photo-spot="${index}" aria-label="${safe(p.spot)} 상세정보"><img loading="lazy" id="cityStrip${i}" alt="${safe(p.spot)} 사진"><strong>${safe(p.spot)} →</strong></button><span class="mini-credit">${photoCredit(p,true)} · ${safe(photoAgeLabel(p))}</span></article>`;
 }).join('');
 items.forEach((p,i)=>setCuratedImage($('cityStrip'+i),p,p.spot,null));
 $('cityPhotoGallery').querySelectorAll('[data-city-photo-spot]').forEach(b=>b.onclick=()=>openDetail(+b.dataset.cityPhotoSpot));
}
function renderInspiration(){
 const picks=['나트랑','도쿄','싱가포르','파리','오사카','발리'];
 const selected=picks.map(city=>({city,p:distinctCityPhotos(city,1)[0]})).filter(x=>x.p);
 $('inspireGallery').innerHTML=selected.map(({city,p},i)=>`<article class="inspire-tile"><button type="button" data-inspire-city="${safe(city)}" aria-label="${safe(city)} 여행정보 열기"><img loading="lazy" id="inspireImg${i}" alt="${safe(p.spot)} 실제 관광지 사진"><span class="tile-caption">${safe(city)} · ${safe(p.spot)}<small>사진과 여행정보 보러 가기 ↗</small></span></button><div class="inspire-credit">${photoCredit(p,true)} · ${safe(photoAgeLabel(p))}</div></article>`).join('');
 selected.forEach(({p},i)=>setCuratedImage($('inspireImg'+i),p,p.spot,null));
 $('inspireGallery').querySelectorAll('[data-inspire-city]').forEach(b=>b.onclick=()=>selectCityForPlan(b.dataset.inspireCity));
}
function selectCityForPlan(city){
 if(!DATA[city])return false;
 const sameCity=$('city').value===city;
 const hasPlan=days.some(day=>day.length>0)||costs.some(x=>num(x)>0)||$('memo').value.trim().length>0;
 if(!sameCity&&hasPlan&&!window.confirm('현재 여행 일정·경비가 초기화됩니다. 먼저 브라우저에 저장하거나 파일로 백업하셨나요? 계속할까요?'))return false;
 if(!sameCity){currentCityMood='all';loaded=null;manual=false;entryDateEdited=false;entryChecks={};$('city').value=city;days=[];costs=Array(8).fill(0);syncDays();nameAuto();renderCosts();renderDays();}
 renderSpots();refresh();refreshCurrency();show('planner');return true;
}
const HERO_FILES=["Gardens by the Bay at night, Singapore, 20240121 2051 2883.jpg","Shibuya crossing, Tokyo, Japan.jpg","Tegalalang Rice Terraces.jpg","2025-09-06 12-23-23 Seine-Paris.jpg","Magellan's Cross in Cebu City.jpg","Umeda Sky Building seen from Lucua at night.jpg","Coast of Nha Trang, Vietnam. June 2025.jpg","Qiche Road (Curve), Jiufen, New Taipei, Feb 2025.jpg","Boats with lanterns on the Thu Bon river IMG 3864.jpg"];
let heroSlide=0,heroRequestId=0;
function showHeroPhoto(index){
 heroSlide=(index+HERO_FILES.length)%HERO_FILES.length;
 const p=PHOTO_CATALOG.find(x=>x.file===HERO_FILES[heroSlide]);
 const count=$('heroPhotoCount');if(count)count.textContent=`${heroSlide+1} / ${HERO_FILES.length}`;
 if(!p)return;
 const requestId=++heroRequestId;
 $('heroPhotoCredit').textContent=`${p.city} · ${p.spot} 사진 불러오는 중…`;
 const probe=new Image();
 probe.onload=()=>{
  if(requestId!==heroRequestId)return;
  document.querySelector('.hero').style.setProperty('--hero-photo',`url("${p.url}")`);
  $('heroPhotoCredit').innerHTML=`실제 장소 사진: ${safe(p.city)} · ${safe(p.spot)} · ${photoCredit(p,true)} · ${safe(photoAgeLabel(p))}`;
 };
 probe.onerror=()=>{
  if(requestId!==heroRequestId)return;
  document.querySelector('.hero').style.removeProperty('--hero-photo');
  $('heroPhotoCredit').innerHTML=`⚠️ 외부 사진 연결 실패 · 그라데이션 대체 배경 · ${photoCredit(p,true)}`;
 };
 probe.src=p.url;
}
function setupHeroPhoto(){
 $('heroPrev').onclick=()=>showHeroPhoto(heroSlide-1);
 $('heroNext').onclick=()=>showHeroPhoto(heroSlide+1);
 showHeroPhoto(0);
 window.setInterval(()=>{if(!document.hidden)showHeroPhoto(heroSlide+1)},9000);
}

let detailPhotos=[],detailPhotoIndex=0;
function chooseDetailPhoto(index){
 if(!detailPhotos.length)return;
 detailPhotoIndex=(index+detailPhotos.length)%detailPhotos.length;
 const p=detailPhotos[detailPhotoIndex],place=DATA[$('city').value].spots[spotIndex][0];
 $('detailImageNote').innerHTML=photoCredit(p)+'<br><span class="photo-age">'+safe(photoAgeLabel(p))+'</span>';
 setCuratedImage($('detailImage'),p,place,$('detailImageNote'));
 $('detailCounter').textContent=`${detailPhotoIndex+1} / ${detailPhotos.length}`;
 if(!$('photoViewer').classList.contains('hidden'))updatePhotoViewer();
 $('detailPrev').disabled=detailPhotos.length<2;$('detailNext').disabled=detailPhotos.length<2;
 $('detailGalleryItems').querySelectorAll('button').forEach((b,j)=>b.setAttribute('aria-pressed',String(j===detailPhotoIndex)));
}

function renderSpots(){
 const city=$('city').value,c=DATA[city];if(!c)return;
 $('planTitle').textContent=city+' 여행계획';$('cityCountry').textContent=c.country;
 $('cityPhotoCredit').innerHTML=photoCredit(CITY_PHOTO_MAP[city]);
 setCuratedImage($('cityPhoto'),CITY_PHOTO_MAP[city],city,$('cityPhotoCredit'));
 $('cityIntro').textContent=c.intro;renderCityPhotoGallery(city);renderCityGuide(city);renderPhotoWalk(city);renderCityRoute(city);renderSpotFilters(city);renderPhotoCredits(city);
 $('spotDay').innerHTML=days.length?days.map((_,i)=>`<option value="${i}">${i+1}일차 (${dateLabel(i)})</option>`).join(''):'<option value="0">날짜별 일정표 생성 후 선택</option>';
 $('spots').innerHTML=c.spots.map((sp,i)=>{
  const p=spotPhoto(city,sp[0]);
  return `<article class="spot" data-spot-card="${i}"><figure class="spot-figure"><img id="spotImg${i}" loading="lazy" alt="${safe(sp[0])} 사진"><figcaption id="spotCredit${i}">${photoCredit(p,true)}<br><span class="photo-age">${safe(photoAgeLabel(p))}</span></figcaption></figure>${spotGallery(city,sp[0]).length>1?`<div class="spot-mini-gallery" aria-label="${safe(sp[0])} 사진 미리보기">${spotGallery(city,sp[0]).slice(1,3).map((pic,j)=>`<button type="button" class="spot-mini-button" data-photo-preview="${i}" data-photo-pos="${j+1}" title="${safe(pic.label)} 사진 상세보기"><img id="spotThumb${i}_${j}" loading="lazy" alt="${safe(pic.label)} · ${safe(pic.taken)}"><span>사진 ${j+2}</span></button>`).join('')}</div>`:''}<div class="spot-body"><span class="badge">${safe(sp[2])}</span><span class="spot-photo-count">📷 ${spotGallery(city,sp[0]).length}장</span><h3>${safe(sp[0])}</h3><p>${safe(sp[1])}</p><p class="small muted">⏱ 권장 체류 약 ${sp[3]}분</p><div class="actions"><button class="btn alt" data-detail="${i}">상세정보</button><button class="btn" data-add="${i}">+ 일정 추가</button></div></div></article>`;
 }).join('');
 c.spots.forEach((sp,i)=>setCuratedImage($('spotImg'+i),spotPhoto(city,sp[0]),sp[0],$('spotCredit'+i)));
 c.spots.forEach((sp,i)=>spotGallery(city,sp[0]).slice(1,3).forEach((p,j)=>setCuratedImage($('spotThumb'+i+'_'+j),p,sp[0],null)));
 $('spots').querySelectorAll('[data-photo-preview]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.photoPreview),pos=Number(b.dataset.photoPos);openDetail(i);chooseDetailPhoto(pos)});
 document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openDetail(+b.dataset.detail));
 document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addSpot(+b.dataset.add));filterSpots();renderEntryGuide();
}
function addSpot(i){let city=$('city').value,sp=DATA[city].spots[i];if(!days.length){if(!syncDays()){toast('여행 날짜를 먼저 입력하세요');return}renderDays()}let d=Math.min(Math.max(0,+$('spotDay').value||0),days.length-1);if(days[d].some(x=>x.place===sp[0])&&!confirm('이 날짜에 같은 관광지가 있습니다. 한 번 더 추가할까요?'))return;days[d].push({time:'09:00',place:sp[0],memo:sp[1]+' · 권장 체류 약 '+sp[3]+'분',cost:0});active=d;renderDays();refresh();toast((d+1)+'일차에 추가했습니다')}

