function v38CancelDraft(){v38Draft=null;$('v39AutoOptions').classList.add('hidden');$('v39AutoSummary').classList.add('hidden')}
function recommendItinerary(){
 const n=duration();
 if(!n||!DATA[$('city').value]){toast('여행지·출발일·귀국일을 먼저 선택하세요 (1~60일).');return}
 const draft=v38Build($('city').value,n);
 if(!draft.some(d=>d.length)){toast('추천 가능한 관광지가 없습니다.');return}
 v38Draft={city:$('city').value,start:$('start').value,end:$('end').value,days:draft};
 const hasExisting=days.some(d=>d.length);
 v38RenderSummary(draft,hasExisting?'추천 일정 미리보기':'추천 일정 자동 불러오기');
 if(hasExisting){$('v39AutoOptions').classList.remove('hidden');toast('기존 일정이 있습니다. 빈 날짜 추가 또는 전체 교체를 선택하세요.');$('v39AutoSummary').scrollIntoView({block:'nearest',behavior:'smooth'});return}
 $('v39AutoOptions').classList.add('hidden');v38ApplyDraft('replace');
}
function openDayRoute(){
 const arr=(days[active]||[]).filter(x=>x.place&&x.place.trim()).slice().sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'));
 if(!arr.length){toast('먼저 오늘 일정에 관광지를 추가하세요.');return}
 const city=$('city').value,places=arr.slice(0,8).map(x=>x.place+' '+city);
 let url='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(places[0]);
 if(places.length>1){const qs=new URLSearchParams({api:'1',origin:places[0],destination:places[places.length-1],travelmode:'driving'});if(places.length>2)qs.set('waypoints',places.slice(1,-1).join('|'));url='https://www.google.com/maps/dir/?'+qs.toString()}
 if(arr.length>8)toast('지도에는 앞의 8개 장소만 표시합니다.');
 window.open(url,'_blank','noopener,noreferrer');
}
function printItinerary(){
 const t=totals(),title=$('tripName').value.trim()||'나의 여행계획';
 const trip=`<h1>K-TRAVEL PICKS | ${safe(title)}</h1><p class="print-muted">${safe($('city').value)} · ${safe($('start').value)} ~ ${safe($('end').value)} · ${t.people}명 · ${t.nights}박</p>`;
 const money=`<h2>여행 경비 요약</h2><table><tr><th>총경비</th><th>1인당</th><th>항공(전체)</th><th>숙박(전체)</th></tr><tr><td>${won(t.total)}</td><td>${won(t.total/t.people)}</td><td>${won(costs[0]*t.people)}</td><td>${won(costs[1]*t.nights*t.rooms)}</td></tr></table>`;
 const dayHtml=days.map((arr,i)=>`<section class="print-day"><h2>${i+1}일차 · ${safe(dateLabel(i))}</h2>${arr.length?`<table><tr><th style="width:65px">시간</th><th style="width:140px">장소</th><th>메모</th><th style="width:85px">예상비용</th></tr>${arr.slice().sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99')).map(x=>`<tr><td>${safe(x.time||'-')}</td><td>${safe(x.place)}</td><td>${safe(x.memo||'')}</td><td>${won(x.cost)}</td></tr>`).join('')}</table>`:'<p class="print-muted">일정 미정</p>'}</section>`).join('');
 const check=TASKS.map((x,i)=>`${checks[i]?'☑':'□'} ${safe(x)}`).join('　');
  const scheduleNote=`<p class="print-muted">예상 일정 시간 겹침: ${allConflictCount()}건 (관광지 체류시간과 설정한 여유시간 기준 · 실제 이동시간 제외)</p>`;
 $('printSheet').innerHTML=trip+money+scheduleNote+dayHtml+`<h2>여행 준비</h2><p>${check}</p><h2>메모</h2><p style="white-space:pre-wrap">${safe($('memo').value)}</p><p class="print-footer">K-TRAVEL PICKS v43 · 예상 경비와 관광정보는 방문 전 확인하세요. · 인쇄 화면에서 PDF로 저장할 수 있습니다.</p>`;
 window.print();
}


/* v20: show diverse photographs for each city; open the selected original in the existing detail modal. */
function cityStoryPhotos(city,limit=12){
 const all=PHOTO_CATALOG.filter(p=>p.city===city&&p.spot);
 const ordered=all.slice().sort((a,b)=>photoSortKey(b).localeCompare(photoSortKey(a)));
 const result=[],used=new Set();
 for(const p of ordered){if(!used.has(p.spot)){used.add(p.spot);result.push(p)}}
 for(const p of ordered){if(result.length>=limit)break;if(!result.includes(p))result.push(p)}
 return result.slice(0,limit);
}
let currentCityMood='all';
function renderCityPhotoGallery(city){
 const mood=currentCityMood;
 const query=String($('cityPhotoSearch')?.value||'').trim().toLocaleLowerCase();
 const showAll=Boolean($('cityPhotoAll')?.checked);
 const base=mood==='all'?(showAll?PHOTO_CATALOG.filter(p=>p.city===city&&p.spot).sort((a,b)=>photoSortKey(b).localeCompare(photoSortKey(a))):cityStoryPhotos(city,12)):
   PHOTO_CATALOG.filter(p=>p.city===city&&p.spot&&p.sceneType===mood).sort((a,b)=>photoSortKey(b).localeCompare(photoSortKey(a)));
 const matching=base.filter(p=>!query||(p.spot+' '+p.label+' '+(p.scene||'')).toLocaleLowerCase().includes(query));
 const items=matching.slice(0,showAll?200:12);
 $('cityPhotoGalleryCount').textContent=`${items.length}장 표시 · ${city} 전체 ${PHOTO_CATALOG.filter(p=>p.city===city&&p.spot).length}장 · 출처·촬영일 아래 표시`;
 const controls=$('cityMoodControls');
 if(controls)controls.querySelectorAll('[data-city-mood]').forEach(b=>{
   const n=b.dataset.cityMood;b.setAttribute('aria-pressed',String(n===mood));
   b.disabled=n!=='all'&&!PHOTO_CATALOG.some(p=>p.city===city&&p.spot&&p.sceneType===n);
 });
 $('cityPhotoGallery').innerHTML=items.length?items.map((p,i)=>{
  const index=DATA[city].spots.findIndex(x=>x[0]===p.spot);
  return `<article class="city-photo-item"><button type="button" data-city-photo-spot="${index}" data-photo-index="${i}" aria-label="${safe(p.spot)} 사진과 상세정보"><img loading="lazy" id="cityStrip${i}" alt="${safe(p.spot)} · ${safe(p.label)}"><strong>${safe(p.spot)} →</strong></button><span class="mini-credit">${photoCredit(p,true)} · ${safe(photoAgeLabel(p))}</span><a class="city-photo-map" href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent(p.spot+' '+city)}" target="_blank" rel="noopener noreferrer" aria-label="${safe(p.spot)} 지도에서 위치 보기">🗺 지도 보기 ↗</a></article>`;
 }).join(''):'<div class="empty" role="status">일치하는 사진이 없습니다. 검색어 또는 분위기 필터를 변경해 보세요.</div>';
 items.forEach((p,i)=>setCuratedImage($('cityStrip'+i),p,p.spot,null));
 $('cityPhotoGallery').querySelectorAll('[data-city-photo-spot]').forEach(b=>b.onclick=()=>{
  const p=items[Number(b.dataset.photoIndex)];openDetail(Number(b.dataset.cityPhotoSpot));
  const pos=spotGallery(city,p.spot).findIndex(x=>x.file===p.file);if(pos>=0)chooseDetailPhoto(pos);
 });
}

let viewerLastFocus=null,viewerStartX=null;
function updatePhotoViewer(){
 const p=detailPhotos[detailPhotoIndex]||null;
 const place=DATA[$('city').value]?.spots[spotIndex]?.[0]||'관광지';
 $('viewerTitle').textContent=place+' · 실제 사진';
 setCuratedImage($('viewerImage'),p,place,$('viewerCredit'));
 $('viewerCredit').innerHTML=p?photoCredit(p)+'<br>'+safe(photoAgeLabel(p)):'해당 관광지 사진 미확인 · 대체 이미지';
 $('viewerCount').textContent=p?`${detailPhotoIndex+1} / ${detailPhotos.length}`:'사진 없음';
 $('viewerPrev').disabled=detailPhotos.length<2;$('viewerNext').disabled=detailPhotos.length<2;
}
function openPhotoViewer(){
 viewerLastFocus=document.activeElement;
 $('photoViewer').classList.remove('hidden');updatePhotoViewer();$('viewerClose').focus();
}
function closePhotoViewer(){
 $('photoViewer').classList.add('hidden');viewerLastFocus?.focus();
}
$('detailZoom').onclick=openPhotoViewer;
$('viewerClose').onclick=closePhotoViewer;
$('viewerPrev').onclick=()=>chooseDetailPhoto(detailPhotoIndex-1);
$('viewerNext').onclick=()=>chooseDetailPhoto(detailPhotoIndex+1);
$('photoViewer').addEventListener('click',e=>{if(e.target===$('photoViewer'))closePhotoViewer()});
$('viewerImage').addEventListener('touchstart',e=>{viewerStartX=e.changedTouches[0].screenX},{passive:true});
$('viewerImage').addEventListener('touchend',e=>{if(viewerStartX===null)return;const dx=e.changedTouches[0].screenX-viewerStartX;viewerStartX=null;if(Math.abs(dx)>55)chooseDetailPhoto(detailPhotoIndex+(dx<0?1:-1))},{passive:true});
document.addEventListener('keydown',e=>{
 if($('photoViewer').classList.contains('hidden'))return;
 if(e.key==='Escape'){e.stopImmediatePropagation();closePhotoViewer()}
 else if(e.key==='ArrowRight'){e.stopImmediatePropagation();chooseDetailPhoto(detailPhotoIndex+1)}
 else if(e.key==='ArrowLeft'){e.stopImmediatePropagation();chooseDetailPhoto(detailPhotoIndex-1)}
},true);


