function renderV30Spotlight(){
 const files=["Basilica Minore del Sto. Niño de Cebu.jpg", "Basilica del Santo Niño in Cebu City (03) (2025-04-18).jpg", "ICONSIAM at night 06122024.jpg", "Back of IconSiam Facade.jpg", "黒門市場 松本清 大阪市中央区 2025-03-24.jpg", "築地場外市場の若葉(20211107) 01.jpg"];
 const V30_TIPS={"세부|산토니뇨 성당": "외관과 내부를 비교하고, 종교행사·복장 규정을 확인하세요.", "방콕|아이콘시암": "강변 야경과 건축 디테일을 비교하고 귀가 교통을 미리 확인하세요.", "오사카|구로몬 시장": "식당·상점 영업시간을 확인하고 현지 먹거리를 즐겨보세요.", "도쿄|츠키지 장외시장": "아침 방문을 고려하세요. 2021년 식당 사진은 현재와 다를 수 있습니다."};
 const list=files.map(f=>PHOTO_CATALOG.find(p=>p.file===f)).filter(Boolean);
 const box=$('photoDuoGallery');if(!box)return;
 box.innerHTML=list.map((p,i)=>`<article class="photo-duo-card"><button type="button" data-duo-file="${safe(p.file)}" aria-label="${safe(p.spot)} 사진과 여행정보 열기"><img loading="lazy" decoding="async" id="duoImage${i}" alt="${safe(p.spot)} · ${safe(p.label)}"><span class="photo-duo-overlay">${safe(p.label)}<small>${safe(p.taken)} 촬영 · 여행정보 열기 →</small></span></button><div class="photo-duo-info"><p class="photo-duo-tip">${safe(V30_TIPS[p.city+'|'+p.spot]||'촬영 당시 모습이며 현재와 다를 수 있습니다.')}</p><div class="photo-credit">${photoCredit(p,true)}</div><div class="photo-duo-actions"><a href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent(p.spot+' '+p.city)}" target="_blank" rel="noopener noreferrer">🗺 지도</a><button type="button" data-duo-plan="${safe(p.file)}">+ 일정에 담기</button></div></div></article>`).join('');
 list.forEach((p,i)=>setCuratedImage($('duoImage'+i),p,p.spot,null));
 const navigate=(file,add)=>{const p=PHOTO_CATALOG.find(x=>x.file===file);if(!p||!selectCityForPlan(p.city))return;const i=DATA[p.city].spots.findIndex(sp=>sp[0]===p.spot);if(i<0)return;if(add){addSpot(i);toast('일정에 추가했습니다. 날짜와 시간을 확인하세요.')}else{openDetail(i);const n=spotGallery(p.city,p.spot).findIndex(x=>x.file===p.file);if(n>=0)chooseDetailPhoto(n)}};
 box.querySelectorAll('[data-duo-file]').forEach(b=>b.onclick=()=>navigate(b.dataset.duoFile,false));
 box.querySelectorAll('[data-duo-plan]').forEach(b=>b.onclick=()=>navigate(b.dataset.duoPlan,true));
}


