const ENTRY_CHECK_ITEMS=[['passport','여권 유효기간·비자·입국요건 확인'],['flight','왕복/출국 항공권 및 숙소 예약정보 준비'],['form','해당 국가 전자입국신고·비자 처리 확인'],['proof','QR코드·승인메일·보험 등 필요한 증빙 오프라인 보관'],['recheck','출발 전 공식기관 최신 공지 재확인']];
let entryChecks={},entryDateEdited=false;
function entryIsoOffset(iso,delta){if(!/^\d{4}-\d{2}-\d{2}$/.test(iso||''))return '';let d=new Date(iso+'T12:00:00');if(!Number.isFinite(d.getTime()))return '';d.setDate(d.getDate()+delta);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function entrySafeLink(url,label){return `<a href="${safe(url)}" target="_blank" rel="noopener noreferrer">${safe(label)} ↗</a>`}
function renderEntryGuide(){
 const city=$('city')?.value,country=DATA[city]?.country,g=ENTRY_GUIDES[country];if(!g)return;
 const dateInput=$('entryArrivalDate');if(!entryDateEdited||!dateInput.value)dateInput.value=$('start').value;
 const arrival=dateInput.value;
 $('entryCountryBadge').textContent=country+' · 공식정보 확인';
 $('entryVisa').innerHTML=`<strong>🛂 입국 자격·비자</strong><p>${safe(g.visa)}</p><p>${safe(g.summary)}</p>`;
 const timed=g.steps.filter(s=>s.when>0);
 const windows=timed.map(s=>`<div class="entry-window-item"><b>${safe(s.name)}</b> · <strong>${safe(entryIsoOffset(arrival,-s.when))}</strong>부터 도착일까지 신청 시기 확인${s.exactHours?' <em>(실제 도착시각 기준 72시간, 날짜 계산은 참고)</em>':''}</div>`).join('');
 $('entryWindow').innerHTML=arrival?(windows||'<div class="entry-window-item">별도 3일 이내 필수 입국신고 일정은 확인되지 않았습니다. 비자·입국 조건을 사전에 확인하세요.</div>'):'현지 도착일을 입력하면 신고 가능 시점이 표시됩니다.';
 $('entryActions').innerHTML=g.steps.map(s=>`<article class="entry-action"><div class="entry-action-top"><strong>${safe(s.name)}</strong><span class="entry-pill">${safe(s.type)}</span></div><p>${safe(s.info)}</p>${entrySafeLink(s.url,'정부 공식 사이트 열기')}</article>`).join('');
 $('entryChecks').innerHTML=ENTRY_CHECK_ITEMS.map(([id,label])=>`<label class="entry-check"><input type="checkbox" data-entry-check="${id}" ${entryChecks[country+'|'+id]?'checked':''}><span>${safe(label)}</span></label>`).join('');
 $('entryChecks').querySelectorAll('[data-entry-check]').forEach(e=>e.addEventListener('change',()=>{entryChecks[country+'|'+e.dataset.entryCheck]=e.checked;refreshEntryProgress()}));
 refreshEntryProgress();
 $('entryTimeline').innerHTML=[['출발 7일 전',-7,'여권·비자·예약·보험·경유지 입국 요건 확인'],['현지 도착 3일 전',-3,'해당 국가 신고 가능 시점 확인 후 공식 사이트에서 작성'],['출발 당일',0,'여권 원본·QR·항공권·숙소 주소·필요한 현지 결제수단 확인']].map(([label,offset,note])=>`<div><b>${safe(label)} <small>${safe(entryIsoOffset(arrival,offset))}</small></b><p>${safe(note)}</p></div>`).join('');
 $('entrySource').innerHTML=`<strong>확인 기준일: 2026-10-18</strong> · ${g.sources.map((u,i)=>entrySafeLink(u,'공식 출처 '+(i+1))).join(' · ')}<br><span>입국 규정은 변경될 수 있습니다. 이 페이지는 정부 사이트를 대신해 신청·승인하지 않습니다.</span>`;
}
function refreshEntryProgress(){let country=DATA[$('city').value]?.country||'';let n=ENTRY_CHECK_ITEMS.filter(([id])=>entryChecks[country+'|'+id]).length;$('entryProgress').textContent=`${n}/${ENTRY_CHECK_ITEMS.length}개 완료`}


/* v32 · photo-first 12-city mini-routes; estimates are editorial, not live routing. */
