function renderPhotoWalk(city){
 const route=PHOTO_WALKS[city]||{title:city+' 하루 산책 코스',when:'오전부터 오후까지',tip:'도시의 대표 명소 3곳을 중심으로 구성한 예시입니다',spots:DATA[city].spots.slice(0,3).map(sp=>sp[0])},box=$('photoWalkCards');if(!route||!box)return;
 $('photoWalkTitle').textContent=route.title;
 $('photoWalkWhen').textContent=`추천 시간대 · ${route.when}`;
 $('photoWalkTip').textContent=route.tip+' · 실제 교통·대기시간은 포함하지 않습니다.';
 box.innerHTML=route.spots.map((name,i)=>{
  const sp=DATA[city].spots.find(s=>s[0]===name),p=spotPhoto(city,name),gallery=spotGallery(city,name);
  return `<article class="photo-walk-card"><button type="button" class="photo-walk-open" data-walk-detail="${i}" aria-label="${safe(name)} 사진과 상세 가이드 보기"><img id="photoWalkImg${i}" loading="lazy" decoding="async" width="420" height="300" alt="${safe(name)} 실제 장소 사진"><span class="photo-walk-number">0${i+1}</span><span class="photo-walk-overlay">${safe(name)} <small>사진 ${gallery.length}장 · 상세 보기 ↗</small></span></button><div class="photo-walk-copy"><p>⏱ 권장 체류 ${sp[3]}분 · ${safe(sp[2])}</p><div class="photo-walk-credit" id="photoWalkCredit${i}">${photoCredit(p,true)} · 확인 ${safe(p?.checked||'기록 없음')}</div></div></article>`;
 }).join('');
 route.spots.forEach((name,i)=>setCuratedImage($('photoWalkImg'+i),spotPhoto(city,name),name,$('photoWalkCredit'+i)));
 box.querySelectorAll('[data-walk-detail]').forEach(b=>b.onclick=()=>{
  const sp=route.spots[Number(b.dataset.walkDetail)],idx=DATA[city].spots.findIndex(s=>s[0]===sp);if(idx>=0)openDetail(idx);
 });
 const locations=route.spots.map(n=>n+' '+city);
 const args=new URLSearchParams({api:'1',origin:locations[0],destination:locations.at(-1),travelmode:['나트랑','다낭','발리','세부'].includes(city)?'driving':'transit'});
 args.set('waypoints',locations.slice(1,-1).join('|'));
 $('photoWalkMap').href='https://www.google.com/maps/dir/?'+args.toString();
 $('photoWalkAdd').onclick=()=>{
  if(!days.length&&!syncDays()){toast('여행 날짜를 먼저 입력하세요');return;}
  const day=Math.min(Math.max(0,Number($('spotDay').value)||0),days.length-1);
  const buffer=Math.max(0,Number($('travelBuffer').value)||0);
  let minute=9*60,added=0;
  for(const name of route.spots){const sp=DATA[city].spots.find(s=>s[0]===name);if(!sp)continue;
   if(!days[day].some(x=>x.place===name)){
    const time=String(Math.floor(minute/60)).padStart(2,'0')+':'+String(minute%60).padStart(2,'0');
    days[day].push({time,place:name,memo:sp[1]+' · 사진 코스 · 권장 체류 '+sp[3]+'분 · 실제 이동시간 별도',cost:0});added++;
   }
   minute+=sp[3]+buffer;
  }
  active=day;renderDays();refresh();toast(added?`${day+1}일차 사진 코스 ${added}곳을 추가했습니다`:'선택한 날짜에 이미 이 코스가 있습니다');
 };
}
function renderGlobalSpotSearch(){
 const box=$('globalSpotResults'),query=$('globalSpotSearch').value.trim().toLocaleLowerCase();
 if(!query){box.classList.add('hidden');box.innerHTML='';return}
 const hits=[];
 for(const [city,d] of Object.entries(DATA))for(const sp of d.spots){
  if((city+' '+d.country+' '+sp[0]+' '+sp[1]+' '+sp[2]).toLocaleLowerCase().includes(query))hits.push({city,sp,p:spotPhoto(city,sp[0])});
 }
 box.classList.remove('hidden');
 box.innerHTML=hits.length?hits.slice(0,12).map((x,i)=>`<button type="button" data-global-hit="${i}" class="global-hit"><img id="globalHitImg${i}" loading="lazy" decoding="async" width="78" height="64" alt="${safe(x.sp[0])} 사진"><span><b>${safe(x.sp[0])}</b><small>${safe(x.city)} · ${safe(x.sp[2])} · 약 ${x.sp[3]}분</small></span><span class="global-hit-arrow">→</span></button>`).join(''):`<p class="hint">검색 결과가 없습니다. 다른 도시·명소·테마를 입력해 보세요.</p>`;
 hits.slice(0,12).forEach((x,i)=>setCuratedImage($('globalHitImg'+i),x.p,x.sp[0],null));
 box.querySelectorAll('[data-global-hit]').forEach(b=>b.onclick=()=>{
  const x=hits[Number(b.dataset.globalHit)];if(!x)return;
  $('globalSpotSearch').value='';box.classList.add('hidden');
  if(!selectCityForPlan(x.city))return;
  const idx=DATA[x.city].spots.findIndex(s=>s[0]===x.sp[0]);if(idx>=0)openDetail(idx);
 });
}
let globalSpotSearchTimer=0;
$('globalSpotSearch').addEventListener('input',()=>{clearTimeout(globalSpotSearchTimer);globalSpotSearchTimer=setTimeout(renderGlobalSpotSearch,100)});
$('globalSpotSearch').addEventListener('keydown',e=>{if(e.key==='Escape'){$('globalSpotSearch').value='';renderGlobalSpotSearch()}});



