function v42Climate(city,month){const v=V42_CLIMATE[city]?.[month-1];const wet=(V42_RAIN[city]||[]).includes(month);const tropical=['베트남','태국','싱가포르','필리핀','인도네시아','말레이시아'].includes(DATA[city]?.country);const season=wet?(tropical?'우기 경향':'비가 잦은 시기'):(tropical?'상대적으로 건조한 시기':'계절별 강수 차이 있음');return{mean:v,wet,season,month,city}}
function v42ArrivalCalc(){const start=$('start').value,time=$('v42DepartureTime').value,hours=Number($('v42FlightHours').value),city=$('city').value;if(!start)return{date:'',hint:'출발일을 선택하세요.'};if(!time||!Number.isFinite(hours)||hours<=0||hours>48)return{date:start,hint:'임시 도착일: 출발일을 그대로 표시했습니다. 출발시각·총 이동시간을 입력하면 시차를 반영해 예상일을 계산합니다.'};const m=start.match(/^(\d{4})-(\d{2})-(\d{2})$/),t=time.match(/^(\d{2}):(\d{2})$/);if(!m||!t)return{date:start,hint:'날짜 또는 출발시각을 확인하세요.'};const utc=Date.UTC(+m[1],+m[2]-1,+m[3],+t[1]-9,+t[2])+Math.round(hours*60)*60000;const fmt=new Intl.DateTimeFormat('en-US',{timeZone:V42_TZ[city]||'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});const o=Object.fromEntries(fmt.formatToParts(new Date(utc)).filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));return{date:`${o.year}-${o.month}-${o.day}`,hint:`현지 도착 예상: ${o.year}-${o.month}-${o.day} ${o.hour}:${o.minute} (${city} 현지시간). 한국 출발시각과 입력한 총 이동시간 기준이며 경유·지연·운항변경은 별도 확인하세요.`}}
function v42SyncArrival(force=false){const result=v42ArrivalCalc();if(!v42ManualArrival||force){$('entryArrivalDate').value=result.date;entryDateEdited=true;v42ManualArrival=false}$('entryDateHint').textContent=v42ManualArrival?'직접 수정한 도착일입니다. 출발일이나 여행지를 변경하면 다시 자동 계산합니다.':result.hint;return result}
const v42OriginalEntry=renderEntryGuide;
renderEntryGuide=function(){v42SyncArrival();v42OriginalEntry();const country=DATA[$('city').value]?.country,g=ENTRY_GUIDES[country];if(g?.checked)$('entrySource').innerHTML=$('entrySource').innerHTML.replace('확인 기준일: 2026-10-18','확인 기준일: '+g.checked);v42RenderClimate();v42RenderPacking()};
function v42RenderClimate(){const city=$('city').value,c=v42Climate(city,v42Month()),v=c.mean;const range=Number.isFinite(v)?`${v-4}~${v+4}℃`:'자료 준비 중';$('v42ClimateSummary').innerHTML=`<strong>🌦 ${safe(city)} · ${c.month}월 여행</strong><div class="v42-climate-tags"><span>${safe(c.season)}</span><span>기온 참고 범위 약 ${range}</span></div><p>월별 기온은 옷차림 선택을 돕는 <b>개략 추정 범위</b>이며 공식 평년값·실시간 예보가 아닙니다. 우기/건기 구분은 지역에 따라 달라지고, 하루에도 날씨가 바뀔 수 있습니다. 산악·해안·태풍·몬순 영향을 별도로 확인하세요.</p><a href="https://www.weather.go.kr/w/weather/worldwide.do" target="_blank" rel="noopener noreferrer">기상청 세계기상 월별 자료 ↗</a> · <a href="https://worldweather.wmo.int/" target="_blank" rel="noopener noreferrer">WMO 공식 도시 기후자료 ↗</a><small>참고자료 확인: 2026-10-23 · 도시별 월별 수치와 직접 대조하지 않은 안내용 추정치</small>`}
function v42PackItems(){const city=$('city').value,country=DATA[city]?.country,cl=v42Climate(city,v42Month()),t=cl.mean;const items=[['passport','🛂 서류','여권 원본·유효기간·비자/입국신고·항공권·숙소 주소'],['sim','📱 통신','eSIM 지원 기종 확인·현지 eSIM/유심 구매·QR 설치 안내 저장'],['insurance','🛡 보험','여행자보험 가입·해외의료비·휴대품·항공 지연 보장 확인'],['money','💳 결제','해외결제 카드·소액 현금·현지 결제앱·카드 해외사용 설정'],['adapter','🔌 전자기기','충전기·보조배터리 기내 반입 규정·현지 콘센트/전압 확인'],['medicine','💊 건강','상비약·개인 처방약·영문 처방전(필요 시)·자외선 차단제'],['bookings','📂 예약','항공·호텔·교통·투어 예약확인서 오프라인 저장']];
if(t<=9)items.push(['clothes','🧥 옷차림','겨울 외투·방한 내의·장갑·목도리·미끄럼 방지 신발']);else if(t<=18)items.push(['clothes','🧥 옷차림','긴팔·얇은 니트·가벼운 재킷·아침저녁 겹쳐 입을 옷']);else if(t<=24)items.push(['clothes','👕 옷차림','반팔·긴팔·가벼운 겉옷·편한 운동화']);else items.push(['clothes','👕 옷차림','통풍 잘되는 반팔·반바지·모자·선글라스·수분 보충 용품']);
if(cl.wet)items.push(['rain','🌧 비 대비','접이식 우산·가벼운 우비·방수 가방·여분 양말·미끄럼 방지 신발']);else items.push(['weather','☀️ 날씨 대비','일기예보 확인·휴대용 우산·자외선 차단제']);
if(['일본','대만','미국'].includes(country))items.push(['plug','🔌 전원','A/B형 플러그 등 현지 콘센트 규격 확인·변환 어댑터 준비']);
if(['중국'].includes(country))items.push(['apps','📲 현지 앱','현지 결제앱·지도·통신 서비스·인터넷 접속환경 사전 확인']);
if(['베트남','태국','인도네시아','필리핀','말레이시아'].includes(country))items.push(['mosquito','🦟 야외','모기 기피제·가려움 완화제·햇빛 차단 용품']);
if(['오키나와','세부','보라카이','발리','나트랑','푸꾸옥','코타키나발루'].includes(city))items.push(['beach','🏖 해변','수영복·래시가드·방수팩·샌들·해양투어 안전/기상 확인']);
return items}
function v42RenderPacking(){const city=$('city').value,month=v42Month(),items=v42PackItems(),prefix=city+'|'+month+'|',done=items.filter(x=>v42PackChecks[prefix+x[0]]).length;$('v42PackingCount').textContent=`${done}/${items.length}개 완료`;$('v42PackingList').innerHTML=items.map(([id,cat,label])=>`<label class="v42-pack-item"><input type="checkbox" data-v42-pack="${id}" ${v42PackChecks[prefix+id]?'checked':''}><span><b>${safe(cat)}</b><small>${safe(label)}</small></span></label>`).join('');$('v42PackingList').querySelectorAll('[data-v42-pack]').forEach(el=>el.onchange=()=>{v42PackChecks[prefix+el.dataset.v42Pack]=el.checked;v42RenderPacking()})}
function v42PhotoAudit(){const missing=Object.entries(DATA).flatMap(([city,d])=>d.spots.filter(s=>!spotPhoto(city,s[0])).map(s=>city+' · '+s[0]));const covered=120-missing.length;$('v42PhotoAudit').innerHTML=`<strong>📷 관광명소 사진 현황: ${covered}/120곳</strong> · 확인된 사진이 없는 명소 ${missing.length}곳. <details><summary>미확인 명소 목록 보기</summary><p>${missing.map(safe).join(' · ')}</p></details><small>v42 신규 ${V42_PHOTOS.length}곳: ${V42_PHOTOS.map(p=>safe(p.city+" "+p.spot)).join(" · ")}. 출처·라이선스·촬영일 확인, 외부 이미지 실제 로딩은 미검증.</small>`}
const v42OldSnap=snap;snap=function(){return{...v42OldSnap(),v42DepartureTime:$('v42DepartureTime').value,v42FlightHours:$('v42FlightHours').value,v42ManualArrival,v42PackChecks:{...v42PackChecks},schema:8}};
const v42OldLoad=load;load=function(x){v42PackChecks=x.v42PackChecks&&typeof x.v42PackChecks==='object'?x.v42PackChecks:{};$('v42DepartureTime').value=x.v42DepartureTime||'';$('v42FlightHours').value=x.v42FlightHours||'';v42ManualArrival=!!x.v42ManualArrival;v42OldLoad(x);v42SyncArrival();renderEntryGuide()};
function v42Init(){for(const id of ['v42DepartureTime','v42FlightHours'])$(id).addEventListener('input',()=>{v42ManualArrival=false;v42SyncArrival(true);renderEntryGuide()});$('v42ArrivalReset').addEventListener('click',()=>{v42ManualArrival=false;v42SyncArrival(true);renderEntryGuide()});$('entryArrivalDate').addEventListener('input',()=>{v42ManualArrival=true;entryDateEdited=true});for(const id of ['start','city'])$(id).addEventListener('change',()=>{v42ManualArrival=false;v42SyncArrival(true);renderEntryGuide()});$('quickGo').addEventListener('click',()=>{v42ManualArrival=false;v42SyncArrival(true);renderEntryGuide()});v42PhotoAudit();renderEntryGuide()}
